\language "nederlands"
\version "2.24.0"

\header {
  title = "Suite in the Style of Boismortier"
  composer = "Johann-Joseph Boismortier"
  tagline = ##f
}

global = {
  \key d \major
  \time 4/4
  \override Score.BarNumber.break-visibility = ##(#f #f #t)
}

dessus = \relative c' {
  \clef treble
  \global
  \repeat volta 2 {
    a8( bes) c4 d8( e) f4 g8( a) |
    bes4 a8( g) f4 e8( d) c4 |
    bes8( a) g4 f8( e) d4 c8( bes) |
    a4 r8 a' g f e d c4 |
  }
  \repeat volta 2 {
    bes8( a) g4 f8( e) d4 c8( bes) |
    a4 g8( f) e4 d8( c) bes4 |
    a'8( g) f4 e8( d) c4 bes8( a) |
    g4 f8( e) d4 c8( bes) a4 |
  }
}

\score {
  \new StaffGroup <<
    \new Staff \dessus
  >>
  \layout { }
}

\language "nederlands"
\version "2.24.0"

\header {
  composer = "Boismortier"
  period = "Late Baroque"
  musical_form = "suite"
  ensemble = "violin, bassoon, contrabass, oboe, flute, viola"
  part = "dessus"
}

dessus = {
  \time 4/4
  \key c \major

  % Movement 1
  c'4 d' e' f' | g' a' b' c'' | d'' e'' f'' g'' | a'' b'' c'' d'' |
  e'' f'' g'' a'' | b'' c'' d'' e'' | f'' g'' a'' b'' | c''1 \bar "|."

  % Movement 2
  e'4 f' g' a' | b' c'' d'' e'' | f'' g'' a'' b'' | c''1 |
  c''4 d'' e'' f'' | g'' a'' b'' c'' | d'' e'' f'' g'' | a''1 \bar "|."

  % Movement 3
  c'4 d' e' f' | g' a' b' c'' | d'' e'' f'' g'' | a'' b'' c'' d'' |
  e'' f'' g'' a'' | b'' c'' d'' e'' | f'' g'' a'' b'' | c''1 \bar "|."

  % Movement 4
  e'4 f' g' a' | b' c'' d'' e'' | f'' g'' a'' b'' | c''1 |
  c''4 d'' e'' f'' | g'' a'' b'' c'' | d'' e'' f'' g'' | a''1 \bar "|."
}

\score {
  \new StaffGroup <<
    \new Staff \with { instrumentName = "Violin" } { \dessus }
    \new Staff \with { instrumentName = "Bassoon" } { \dessus }
    \new Staff \with { instrumentName = "Contrabass" } { \dessus }
    \new Staff \with { instrumentName = "Oboe" } { \dessus }
    \new Staff \with { instrumentName = "Flute" } { \dessus }
    \new Staff \with { instrumentName = "Viola" } { \dessus }
  >>
  \layout { }
  \midi { }
}
